    if s is None:
        return ''
    elif hasattr(s, '__html__'):
        return text_type(s.__html__())
    if not isinstance(s, string_types):
        s = text_type(s)
    return s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;')

